{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Weight each training interaction by the inverse square root of its user's training-history length. This may reduce long-history users' influence on the frequency feature across all four datasets. Retain the existing transform, attenuation and checkpoint buffer, so inference remains consistent.",
      "edits": [
        {
          "find": "    training_counts = np.zeros(itemnum + 1, dtype=np.float64)\n    for history in user_train.values():\n        np.add.at(training_counts, np.asarray(history, dtype=np.int64), 1.0)\n",
          "replace": "    training_counts = np.zeros(itemnum + 1, dtype=np.float64)\n    for history in user_train.values():\n        if not history:\n            continue\n        interaction_weight = 1.0 / math.sqrt(len(history))\n        np.add.at(training_counts, np.asarray(history, dtype=np.int64), interaction_weight)\n"
        }
      ]
    }
  ],
  "change_summary": "Use history-length-weighted training frequencies for all four category models. Preserve the existing normalization, square root, attenuation, architecture and checkpoint-backed predictor."
}
